for f in range(1,265):
    hou.setFrame(f); P.append(list(B.worldTransform().extractTranslates()))
P=np.array(P)
def res(sig,a,b,mode):
    out=[]
    for f in range(a,b+1):
        i=f-1
        if mode=='trunc': lo=max(0,i-6); hi=min(len(sig),i+7)
        elif mode=='seg':  # MA computed within segment only
            lo=max(a-1,i-6); hi=min(b,i+7)
        out.append(sig[i]-sig[lo:hi].mean(axis=0))
    return np.array(out)
R={}
for mode in ['trunc','seg']:
    for name,sl in [('xyz',slice(0,3)),('y',slice(1,2))]:
        r1=res(P[:,sl],1,96,mode); r2=res(P[:,sl],108,128,mode)
        R[mode+name]=float(np.sqrt((r2**2).sum(1).mean())/np.sqrt((r1**2).sum(1).mean()))
result=R
